INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-relevo-de-la-selva-animal', 'El Relevo de la Selva Animal', 'Dinámica de relevos expresivos y coordinación zoológica donde las patrullas compiten imitando el desplazamiento y sonido de distintos animales.', '<h2>📜 Descripción de El Relevo de la Selva Animal</h2>
<p><b>El Relevo de la Selva Animal</b> es una dinámica scout de velocidad adaptativa, expresión corporal y agilidad de grupo. En esta competencia recreativa, las patrullas o seisenas se organizan en hileras tras una línea de partida. Cada participante recibe una tarjeta o consigna secreta con una especie animal (ej. <i>''Canguro''</i>, <i>''Oso''</i>, <i>''Serpiente''</i> o <i>''Águila''</i>). Al toque de silbato, el primer competidor debe desplazarse hacia la línea de meta imitando fielmente la marcha kinésica y el sonido característico del animal asignado, entregar el testimonio a su compañero de relevo y retornar al final de la hilera.</p>
<p>Esta actividad desarrolla el desahogo de energías, la desinhibición y el trabajo en equipo en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Relevo de la Selva Animal?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Alineación de Patrullas:</b> Se ubican las seisenas en hileras paralelas tras la línea de salida en el campo abierto o salón.</li>
  <li><b>Sorteo de Especies:</b> El dirigente entrega a cada corredor el nombre del animal que deberá representar durante su turno de relevo.</li>
  <li><b>La Marcha de la Selva:</b> Al sonido de partida, el scout inicia el trayecto hacia la posta opuesta avanzando con el estilo de desplazamiento del animal (ej. saltos de rana, marcha de cuadrúpedo o vuelo de ave).</li>
  <li><b>Entrega del Testimonio:</b> Al llegar al punto de retorno, el scout emite la voz o rugido del animal y choca la mano con el siguiente corredor para dar la salida.</li>
  <li><b>Llegada Colectiva:</b> La primera seisena o patrulla en completar todos sus relevos de forma fluida y expresiva resulta ganadora.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Relevo de la Selva Animal</h2>
<p>La actividad valora la expresividad kinésica y la velocidad en el Tally:</p>
<ul>
  <li><b>Mayor Fidelidad Expresiva:</b> Otorgar 5 puntos a la patrulla cuyos integrantes interpreten con mayor realismo los movimientos de la fauna.</li>
  <li><b>Velocidad de Relevo:</b> Otorgar 3 puntos al equipo que complete el recorrido en el menor tiempo global.</li>
  <li><b>Espíritu de Manada:</b> Otorgar 3 puntos a la unidad que anime a sus corredores con mayor entusiasmo durante la competencia.</li>
</ul>', '/uploads/el-relevo-de-la-selva-animal.webp', 'publicado', '{"areas": ["corporalidad", "creatividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Exterior", "Campo Abierto", "Interior", "Salón"], "materiales": ["Tarjetas de Animales"], "objetivos": ["Desfogue de Energías", "Desarrollar la motricidad", "Estimular la agilidad", "Trabajo en equipo"], "justificacion_areas": "El Relevo de la Selva Animal potencia la corporalidad al afinar la coordinación motriz gruesa, el equilibrio tónico en marcha de cuadrúpedo y el desahogo saludable de energía física. Desarrolla la creatividad al requerir la adaptación dramática de movimientos y sonidos animales frente al equipo.", "variaciones": "<b>Relevo Nocturno en la Selva:</b> Realizar la posta a oscuras guíados por linternas en la cancha de campamento.<br><b>Relevo de Sonidos Puros:</b> El corredor realiza el trayecto de espaldas emitiendo únicamente la voz del animal.<br><b>Relevo de Seisena de Mowgli:</b> Cada lobato representa a los animales del Libro de las Tierras Vírgenes (Baloo, Bagheera, Kaa, Hathi).", "recomendaciones": "Verificar que el piso no tenga piedras o superficies resbaladizas para los desplazamientos en cuadrúpedo. Adaptar la exigencia física a las capacidades del grupo.", "objetivos_educativos": [{"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Participando con entusiasmo en la competencia de relevos para ganar agilidad y flexibilidad corporal."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Afinando el control de extremidades al imitar desplazamientos en cuadrúpedo y saltos."}, {"id": "273f60b8-7953-4416-97c3-e8c83615364f", "area": "Corporalidad", "unidad": "Compañía", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Ejercitando la resistencia física y la velocidad en juegos de posta grupal."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "unidad": "Compañía", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Respetando la condición física de las compañeras durante la carrera de relevos."}, {"id": "5c9843d1-39fd-4298-870c-5e46f29ffbf6", "area": "Corporalidad", "unidad": "Tropa", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Desarrollando la potencia cardiovascular y la agilidad muscular en la Tropa."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "unidad": "Tropa", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Promoviendo el autocuidado y el juego limpio en la competencia física de patrulla."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando los movimientos característicos de la fauna para replicarlos con expresividad."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Adaptando con rapidez los gestos dramáticos del animal asignado en la carrera."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Proponiendo técnicas creativas de desplazamiento para optimizar el tiempo de posta."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando las ventajas de coordinación táctica según la especie animal representada."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando entusiasmo e improvisación teatral en cada turno de relevo."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando señas y gestos corporales para motivar a la patrulla."}]}'::jsonb, NOW(), NOW(), NULL, NULL
